const results = [];
for (const item of $input.all()) {
  const url = item.json.source_url;
  let sourceType = '';
  if (url.includes('youtube.com') || url.includes('youtu.be')) sourceType = 'youtube';
  else if (url.includes('instagram.com/reel') || url.includes('instagram.com/p/')) sourceType = 'instagram';

  if (!sourceType) {
    results.push({ json: { source_url: url, source_type: 'unknown', video_id: '', title: 'ERROR: Unsupported URL', transcript: '', duration_seconds: 0, aspect_ratio: '16:9', video_stream_url: '' } });
    continue;
  }

  if (sourceType === 'youtube') {
    let vid = '';
    if (url.includes('v=')) vid = url.split('v=')[1].split('&')[0];
    else if (url.includes('youtu.be/')) vid = url.split('youtu.be/')[1].split('?')[0];
    else if (url.includes('/shorts/')) vid = url.split('/shorts/')[1].split('?')[0];
    if (!vid) { results.push({ json: { source_url: url, source_type: 'youtube', video_id: '', title: 'ERROR: Invalid YouTube URL', transcript: '', duration_seconds: 0, aspect_ratio: '16:9', video_stream_url: '' } }); continue; }

    let title = '';
    try {
      const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://www.youtube.com/oembed?format=json&url=https://www.youtube.com/watch?v=' + vid });
      title = (typeof r === 'string' ? JSON.parse(r) : r).title || '';
    } catch (e) { title = 'Untitled Video'; }

    let transcript = ''; let duration_seconds = 0; let videoStreamUrl = '';
    try {
      const playerResp = await this.helpers.httpRequest({ method: 'POST', url: 'https://www.youtube.com/youtubei/v1/player?prettyPrint=false', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ videoId: vid, context: { client: { clientName: 'ANDROID', clientVersion: '19.09.37', hl: 'en' } } }) });
      const pd = typeof playerResp === 'string' ? JSON.parse(playerResp) : playerResp;
      duration_seconds = parseInt(pd?.videoDetails?.lengthSeconds || '0', 10);

      // Get video stream URL (360p MP4 preferred for small size)
      const formats = pd?.streamingData?.formats || [];
      const f360 = formats.find(f => f.itag === 18);
      const fAny = formats.find(f => f.mimeType && f.mimeType.includes('video/mp4') && f.url);
      const chosen = f360 || fAny;
      if (chosen && chosen.url) {
        videoStreamUrl = chosen.url;
      }

      // Get transcript
      const tracks = pd?.captions?.playerCaptionsTracklistRenderer?.captionTracks;
      if (tracks && tracks.length > 0) {
        const t = tracks.find(t => t.languageCode === 'en') || tracks[0];
        const caps = await this.helpers.httpRequest({ method: 'GET', url: t.baseUrl + '&fmt=json3' });
        const cd = typeof caps === 'string' ? JSON.parse(caps) : caps;
        transcript = (cd.events || []).filter(e => e.segs).map(e => e.segs.map(s => s.utf8).join('')).join(' ').replace(/\s+/g, ' ').trim();
      }
      if (!transcript) { const desc = pd?.videoDetails?.shortDescription; if (desc && desc.length > 10) transcript = desc; }
      if (!transcript) transcript = 'No transcript available.';
    } catch (e) { transcript = 'Fetch error: ' + e.message; }

    results.push({ json: { source_url: url, source_type: 'youtube', video_id: vid, title, transcript, duration_seconds, aspect_ratio: url.includes('/shorts/') ? '9:16' : '16:9', video_stream_url: videoStreamUrl } });
  }

  if (sourceType === 'instagram') {
    const reelMatch = url.match(/instagram\.com\/(?:reel|reels|p)\/([A-Za-z0-9_-]+)/);
    const shortcode = reelMatch ? reelMatch[1] : '';
    if (!shortcode) { results.push({ json: { source_url: url, source_type: 'instagram', video_id: '', title: 'ERROR: Invalid Instagram URL', transcript: '', duration_seconds: 0, aspect_ratio: '9:16', video_stream_url: '' } }); continue; }
    let title = '';
    try {
      const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.instagram.com/oembed/?url=' + encodeURIComponent(url) + '&format=json', headers: { 'User-Agent': 'Mozilla/5.0' } });
      const d = typeof r === 'string' ? JSON.parse(r) : r;
      title = d.title || (d.author_name ? 'Instagram Reel by ' + d.author_name : '');
    } catch (e) {}
    if (!title) title = 'Instagram Reel ' + shortcode;
    results.push({ json: { source_url: url, source_type: 'instagram', video_id: shortcode, title, transcript: title, duration_seconds: 0, aspect_ratio: '9:16', video_stream_url: '' } });
  }
}
return results;

const GEMINI_KEY = 'YOUR_GEMINI_API_KEY';
const item = $input.first().json;

try {
  let fileUri = '';
  let usedVideo = false;

  // STEP 1: Try to download and upload actual video to Gemini File API
  if (item.video_stream_url) {
    try {
      // Download the video (360p MP4, usually 5-20MB)
      const videoResp = await this.helpers.httpRequest({
        method: 'GET',
        url: item.video_stream_url,
        encoding: 'arraybuffer',
        returnFullResponse: true,
        timeout: 60000,
        headers: { 'User-Agent': 'Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36' }
      });

      const videoBuffer = Buffer.from(videoResp.body);
      const videoSizeMB = videoBuffer.length / (1024 * 1024);

      if (videoSizeMB > 0.1 && videoSizeMB < 50) {
        // Upload to Gemini File API using resumable upload
        // Step A: Initiate resumable upload
        const initResp = await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://generativelanguage.googleapis.com/upload/v1beta/files?key=' + GEMINI_KEY,
          headers: {
            'X-Goog-Upload-Protocol': 'resumable',
            'X-Goog-Upload-Command': 'start',
            'X-Goog-Upload-Header-Content-Length': videoBuffer.length.toString(),
            'X-Goog-Upload-Header-Content-Type': 'video/mp4',
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({ file: { displayName: 'source_video.mp4' } }),
          returnFullResponse: true
        });

        const uploadUrl = initResp.headers['x-goog-upload-url'];
        if (!uploadUrl) throw new Error('No upload URL returned from Gemini File API');

        // Step B: Upload the actual video bytes
        const uploadResp = await this.helpers.httpRequest({
          method: 'POST',
          url: uploadUrl,
          headers: {
            'Content-Length': videoBuffer.length.toString(),
            'X-Goog-Upload-Offset': '0',
            'X-Goog-Upload-Command': 'upload, finalize'
          },
          body: videoBuffer,
          returnFullResponse: true,
          timeout: 120000
        });

        const fileInfo = typeof uploadResp.body === 'string' ? JSON.parse(uploadResp.body) : uploadResp.body;
        let fileName = fileInfo?.file?.name;
        fileUri = fileInfo?.file?.uri || '';
        let fileState = fileInfo?.file?.state || 'PROCESSING';

        // Step C: Poll until file is ACTIVE (Gemini needs to process the video)
        let pollCount = 0;
        while (fileState === 'PROCESSING' && pollCount < 30) {
          await new Promise(r => setTimeout(r, 5000));
          pollCount++;
          const statusResp = await this.helpers.httpRequest({
            method: 'GET',
            url: 'https://generativelanguage.googleapis.com/v1beta/' + fileName + '?key=' + GEMINI_KEY
          });
          const statusData = typeof statusResp === 'string' ? JSON.parse(statusResp) : statusResp;
          fileState = statusData.state;
          fileUri = statusData.uri || fileUri;
        }

        if (fileState === 'ACTIVE' && fileUri) {
          usedVideo = true;
        } else {
          fileUri = '';
        }
      }
    } catch (videoErr) {
      // Video download/upload failed, will fall back to text-only
      fileUri = '';
    }
  }

  // STEP 2: Build Gemini request - with video file or text-only
  const parts = [];

  if (usedVideo && fileUri) {
    // Send the actual video file to Gemini
    parts.push({
      fileData: {
        mimeType: 'video/mp4',
        fileUri: fileUri
      }
    });
    parts.push({
      text: 'WATCH THE ENTIRE VIDEO ABOVE carefully. Analyze EVERY scene, shot, and moment.\n\nVideo Title: ' + (item.title || '') + '\nVideo Duration: ' + (item.duration_seconds || 0) + ' seconds\n\nTranscript/Description:\n' + (item.transcript || '').substring(0, 3000) + '\n\nProvide a DETAILED scene-by-scene breakdown of this video. For EACH distinct scene or shot, describe:\n\n1. TIMESTAMP: When does this scene appear (approximate seconds)\n2. PEOPLE: Exact appearance - age, gender, ethnicity, hair, clothing, accessories, expressions, body language\n3. ACTIONS: What are they doing? Specific movements, gestures, interactions\n4. SETTING: Location, indoor/outdoor, background details, props\n5. CAMERA: Shot type (close-up/medium/wide), angle, movement (static/pan/dolly/handheld)\n6. LIGHTING: Natural/artificial, direction, color temperature, shadows\n7. COLORS: Dominant colors, color grading style, saturation\n8. MOOD: Emotional tone of this specific scene\n\nReturn ONLY valid JSON:\n{\n  "scene_count": 5,\n  "scenes": [\n    {\n      "timestamp": "0-5s",\n      "people": "detailed description",\n      "actions": "what happens",\n      "setting": "where",\n      "camera": "shot details",\n      "lighting": "light details",\n      "colors": "color details",\n      "mood": "emotional tone"\n    }\n  ],\n  "overall_style": "complete visual style summary",\n  "consistent_elements": "elements that stay the same throughout (character look, color grade, etc)",\n  "video_narrative": "what story or message does the video tell from start to finish"\n}'
    });
  } else {
    // Fallback: text-only analysis (no video available)
    parts.push({
      text: 'Video Title: ' + (item.title || '') + '\nVideo Duration: ' + (item.duration_seconds || 0) + ' seconds\nAspect Ratio: ' + (item.aspect_ratio || '16:9') + '\n\nFull Transcript/Description:\n' + (item.transcript || '') + '\n\nBased on this transcript, analyze what this video likely shows. Describe in detail:\n1. What people/subjects appear and what they look like\n2. What actions and movements happen\n3. The setting and environment\n4. The likely visual style, colors, and lighting\n5. The mood and energy\n\nReturn ONLY valid JSON:\n{\n  "scene_count": 4,\n  "scenes": [{"timestamp":"0-15s","people":"desc","actions":"desc","setting":"desc","camera":"desc","lighting":"desc","colors":"desc","mood":"desc"}],\n  "overall_style": "visual style summary",\n  "consistent_elements": "recurring elements",\n  "video_narrative": "story from start to finish"\n}'
    });
  }

  const body = {
    contents: [{ role: 'user', parts: parts }],
    systemInstruction: {
      parts: [{ text: 'You are a professional video analyst. ' + (usedVideo ? 'You are watching an actual video. Describe EXACTLY what you see in each scene - specific details about people, clothing, environment, camera work, colors, and lighting. Be extremely precise.' : 'Based on the transcript, infer the likely visual content.') + ' Your scene-by-scene analysis will be used to recreate this video, so every detail matters. Output ONLY valid JSON, no markdown fences.' }]
    },
    generationConfig: { temperature: 0.2 }
  };

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=' + GEMINI_KEY,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    timeout: 120000
  });

  const resp = typeof response === 'string' ? JSON.parse(response) : response;

  if (resp.error) throw new Error('Gemini API error: ' + JSON.stringify(resp.error));
  if (resp.candidates?.[0]?.finishReason === 'SAFETY') throw new Error('Gemini SAFETY filter blocked this video');

  let analysisText = resp.candidates?.[0]?.content?.parts?.[0]?.text || '';
  if (!analysisText) throw new Error('Empty Gemini response: ' + JSON.stringify(resp).substring(0, 300));

  analysisText = analysisText.replace(/[\x00-\x1F\x7F]/g, ' ');

  let analysis;
  try { analysis = JSON.parse(analysisText); } catch (e) {
    const m = analysisText.match(/\{[\s\S]*\}/);
    try { analysis = m ? JSON.parse(m[0]) : { overall_style: analysisText }; } catch (e2) { analysis = { overall_style: analysisText }; }
  }

  return [{
    json: {
      source_url: item.source_url,
      title: item.title,
      transcript: item.transcript,
      duration_seconds: item.duration_seconds,
      aspect_ratio: item.aspect_ratio,
      source_type: item.source_type,
      analysis: JSON.stringify(analysis),
      debug_error: '',
      debug_method: usedVideo ? 'VIDEO_UPLOADED' : 'TEXT_ONLY_FALLBACK'
    }
  }];
} catch (err) {
  return [{
    json: {
      source_url: item.source_url || '',
      title: item.title || '',
      transcript: item.transcript || '',
      duration_seconds: item.duration_seconds || 0,
      aspect_ratio: item.aspect_ratio || '16:9',
      source_type: item.source_type || '',
      analysis: '{}',
      debug_error: 'ANALYZE ERROR: ' + err.message,
      debug_method: 'FAILED'
    }
  }];
}

const GEMINI_KEY = 'YOUR_GEMINI_API_KEY';
const item = $input.first().json;
const transcript = (item.transcript || '').substring(0, 3000);

if (item.debug_error) {
  return [{
    json: {
      source_url: item.source_url || '', video_title: item.title || '', status: 'error',
      segment_1_prompt: '', segment_2_prompt: '', segment_3_prompt: '', segment_4_prompt: '',
      global_style: '', character_description: '',
      segment_1_video_url: '', segment_2_video_url: '', segment_3_video_url: '', segment_4_video_url: '',
      combined_video_url: '', completed_at: new Date().toISOString(),
      debug_error: item.debug_error
    }
  }];
}

try {
  const userText = 'VIDEO ANALYSIS:\n' + (item.analysis || '') + '\n\nTitle: ' + (item.title || '') + '\nDuration: ' + (item.duration_seconds || 0) + 's\n\nTranscript: ' + transcript + '\n\n---\n\nWrite 4 simple video prompts inspired by this video. The prompts will be used in AI video generators (Sora, Seedance).\n\nSAFETY RULES (prompts get rejected if you break these):\n- NEVER describe real people, celebrities, public figures, or named individuals\n- NEVER mention ethnicity, race, or nationality of people\n- NEVER mention real brand names, company names, or copyrighted characters\n- NEVER reference the original video, YouTube, or any platform\n- Use GENERIC character descriptions only: "a person", "a woman", "a man", "someone"\n- Describe clothing, hair style, and actions but keep people anonymous and generic\n- Keep it fully fictional and original\n\nPROMPT FORMAT RULES:\n- MAX 50-70 words each. Short and simple.\n- Plain natural English. Describe what the viewer sees.\n- Include: who (generic person), what they do, where, lighting, colors\n- DO NOT use timestamps like [0-3s]\n- DO NOT use technical terms (dolly, pan, close-up, medium shot, key light)\n- DO NOT end with tag lists (cinematic, 4K, photorealistic, etc.)\n- DO NOT use negative words (no, not, without, never)\n- DO NOT mention text, speech, dialogue, audio, or watermarks\n\nGOOD EXAMPLE: "A person with long brown hair wearing a white dress walks through a sunlit lavender field, gently touching the flowers. A warm breeze moves their hair. Golden afternoon light and soft warm colors fill the scene."\n\nBAD EXAMPLE: "A 25-year-old Caucasian woman named Sarah from the YouTube video walks through a field. Close-up shot. Cinematic, 4K, photorealistic, shallow depth of field."\n\nCONTINUITY: Same generic character and setting across all 4. Each flows naturally into the next.\n\nReturn ONLY valid JSON (no markdown):\n{\n  "segment_1_prompt": "simple scene under 70 words",\n  "segment_2_prompt": "continues from segment 1",\n  "segment_3_prompt": "continues from segment 2",\n  "segment_4_prompt": "continues from segment 3",\n  "global_style": "the overall visual look",\n  "character_description": "generic character description used across all segments"\n}';

  const body = {
    contents: [{ role: 'user', parts: [{ text: userText }] }],
    systemInstruction: { parts: [{ text: 'Write simple, short, SAFE video prompts for AI video generators. These tools have strict content policies and will reject prompts that describe real people, mention ethnicity or race, include brand names, or are too long/technical. All characters must be generic and fictional. Keep prompts under 70 words. Use plain natural language. Describe the visual style and actions inspired by the video analysis, but make everything fictional and generic. Output ONLY valid JSON.' }] },
    generationConfig: { temperature: 0.4 }
  };

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=' + GEMINI_KEY,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    timeout: 120000
  });

  const resp = typeof response === 'string' ? JSON.parse(response) : response;
  if (resp.error) throw new Error('Gemini API error: ' + JSON.stringify(resp.error));
  if (resp.candidates?.[0]?.finishReason === 'SAFETY') throw new Error('SAFETY filter blocked');

  let text = resp.candidates?.[0]?.content?.parts?.[0]?.text || '';
  if (!text) throw new Error('Empty response: ' + JSON.stringify(resp).substring(0, 300));
  text = text.replace(/[\x00-\x1F\x7F]/g, ' ');

  let parsed;
  try { parsed = JSON.parse(text); } catch (e) {
    const m = text.match(/\{[\s\S]*\}/);
    try { parsed = m ? JSON.parse(m[0]) : null; } catch (e2) { parsed = null; }
  }

  if (!parsed || !parsed.segment_1_prompt) throw new Error('Parse failed. Raw: ' + text.substring(0, 300));

  return [{
    json: {
      source_url: item.source_url || '', video_title: item.title || '', status: 'prompts_ready',
      segment_1_prompt: parsed.segment_1_prompt || '',
      segment_2_prompt: parsed.segment_2_prompt || '',
      segment_3_prompt: parsed.segment_3_prompt || '',
      segment_4_prompt: parsed.segment_4_prompt || '',
      global_style: parsed.global_style || '',
      character_description: parsed.character_description || '',
      segment_1_video_url: '', segment_2_video_url: '', segment_3_video_url: '', segment_4_video_url: '',
      combined_video_url: '', completed_at: new Date().toISOString(),
      debug_error: 'Method: ' + (item.debug_method || 'unknown')
    }
  }];
} catch (err) {
  return [{
    json: {
      source_url: item.source_url || '', video_title: item.title || '', status: 'error',
      segment_1_prompt: '', segment_2_prompt: '', segment_3_prompt: '', segment_4_prompt: '',
      global_style: '', character_description: '',
      segment_1_video_url: '', segment_2_video_url: '', segment_3_video_url: '', segment_4_video_url: '',
      combined_video_url: '', completed_at: new Date().toISOString(),
      debug_error: 'PROMPTS ERROR: ' + err.message
    }
  }];
}

const item = $input.first().json;
const url1 = (item.segment_1_video_url || '').trim();
const url2 = (item.segment_2_video_url || '').trim();
const url3 = (item.segment_3_video_url || '').trim();
const url4 = (item.segment_4_video_url || '').trim();
const status = (item.status || '').trim();

// Collect all filled URLs (at least 1 needed)
const filledUrls = [url1, url2, url3, url4].filter(u => u);
const readyToCombine = status === 'prompts_ready' && filledUrls.length >= 1;

if (readyToCombine) {
  return [{ json: { source_url: item.source_url || '', video_title: item.video_title || '', segment_1_video_url: url1, segment_2_video_url: url2, segment_3_video_url: url3, segment_4_video_url: url4, total_segments: filledUrls.length } }];
}
return [];

const data = $input.first().json;
const rawUrls = [data.segment_1_video_url, data.segment_2_video_url, data.segment_3_video_url, data.segment_4_video_url].filter(u => u && u.trim());

if (rawUrls.length < 1) return [{ json: { ...data, status: 'error', combined_video_url: '', error: 'No video URLs found' } }];

// Convert Google Drive share links to direct download URLs
function toDirectUrl(url) {
  const driveMatch = url.match(/drive\.google\.com\/file\/d\/([a-zA-Z0-9_-]+)/);
  if (driveMatch) return 'https://drive.google.com/uc?export=download&id=' + driveMatch[1];
  const driveMatch2 = url.match(/drive\.google\.com\/open\?id=([a-zA-Z0-9_-]+)/);
  if (driveMatch2) return 'https://drive.google.com/uc?export=download&id=' + driveMatch2[1];
  return url;
}

const directUrls = rawUrls.map(toDirectUrl);

return [{
  json: {
    source_url: data.source_url || '',
    video_title: data.video_title || '',
    status: 'ready_to_combine',
    combined_video_url: directUrls.join(' | '),
    total_segments: directUrls.length,
    error: ''
  }
}];
